package dev.pocketengine.features.remote;

import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.RemoteOwnerWorkflows;
import dev.pocketengine.features.channels.ChannelsModule;
import dev.pocketengine.features.groups.GroupsModule;
import dev.pocketengine.features.groups.host.GroupArtifactStore;
import dev.pocketengine.store.TaskStore;
import java.nio.charset.StandardCharsets;
import java.util.UUID;
import org.json.JSONArray;
import org.json.JSONObject;

/** One existing native group subpage. Original input/job/SQL/artifact/outbox own every durable fact. */
public final class RemoteGroupInputs implements AutoCloseable {
    @FunctionalInterface public interface WindowCurrent {void check();}
    private final GroupsModule groups;private final GroupArtifactStore artifacts;private final TaskStore tasks;private final RemoteOwnerWorkflows owner;private final RemoteModule remote;private final ChannelsModule channels;private final Object nativeActivity;private final WindowCurrent current;
    private final String pageId=UUID.randomUUID().toString(),requestId,parentTask;private volatile boolean closed;private String taskId,inputWindow;private JSONObject inputSnapshot,lastJob,resultOperation,lastDelivery;private GroupsModule.RemoteInputSource source;private ReturnApproval review;
    public RemoteGroupInputs(GroupsModule groups,GroupArtifactStore artifacts,TaskStore tasks,RemoteOwnerWorkflows owner,RemoteModule remote,ChannelsModule channels,Object nativeActivity,WindowCurrent current,String requestId)throws Exception{
        this.groups=groups;this.artifacts=artifacts;this.tasks=tasks;this.owner=owner;this.remote=remote;this.channels=channels;this.nativeActivity=nativeActivity;this.current=current;this.requestId=requestId;check();JSONObject ref=groups.ownerCommand("task.inspect",new JSONObject().put("requestId",requestId));parentTask=ref.getJSONObject("reference").getString("taskId");try{source=groups.remoteInputSourceForOwner(requestId);}catch(SecurityException notReady){/* Original child query/cancel remains available; no source grant fabricated. */}
    }
    public String identity(){return pageId;}
    private void check(){if(closed)throw new SecurityException("原群远端子页已关闭");current.check();}
    private void exactTask(String selected)throws Exception{JSONObject scope=tasks.originalRemoteInputScope(selected);if(scope.optJSONObject("groupInputSource")==null||!requestId.equals(scope.getJSONObject("groupInputSource").getString("requestId"))||!parentTask.equals(scope.getJSONObject("groupInputSource").getString("taskId")))throw new SecurityException("原远端输入不是此原群请求");}
    public JSONObject handle(String action,JSONObject input)throws Exception{
        check();java.util.Set<String> keys=new java.util.HashSet<>();switch(action){case "describe":break;case "environments":keys.add("profileId");break;case "open":keys.addAll(java.util.Set.of("request","taskId"));break;case "input":keys.addAll(java.util.Set.of("command","payload"));break;case "query":case "cancel":keys.add("taskId");break;case "reviewResult":keys.addAll(java.util.Set.of("taskId","replyEventId"));break;case "confirmResult":keys.addAll(java.util.Set.of("digest","contentAndAudienceAcknowledged"));break;case "queryReturn":case "inspectDelivery":keys.addAll(java.util.Set.of("taskId","operationId"));break;default:throw new SecurityException("未知原群远端动作");}
        for(var names=input.keys();names.hasNext();)if(!keys.contains(names.next()))throw new SecurityException("原群远端动作不接收模型提供的scope/凭据/任意URL");
        switch(action){
            case "describe":return snapshot();
            case "environments":{String profile=input.getString("profileId"),generation=remote.profileBindingHash(profile);remote.requireProfileBinding(profile,generation);JSONObject env=remote.handle("environments",new JSONObject().put("profileId",profile).put("_profileBinding",generation));check();remote.requireProfileBinding(profile,generation);return snapshot().put("remoteEnvironments",env).put("selectedProfileId",profile).put("selectedProfileGeneration",generation);}
            case "open":{
                if(inputWindow!=null)owner.close(inputWindow);inputWindow=UUID.randomUUID().toString();taskId=input.optString("taskId").isEmpty()?UUID.randomUUID().toString():input.getString("taskId");if(!input.optString("taskId").isEmpty())exactTask(taskId);source=groups.remoteInputSourceForOwner(requestId);check();inputSnapshot=owner.openGroupInputs(nativeActivity,inputWindow,taskId,input.optJSONObject("request"),source).getJSONObject("snapshot");review=null;return snapshot();}
            case "input":{
                if(inputWindow==null)throw new SecurityException("请重新选择原群来源与目标");String command=input.getString("command");if(!java.util.Set.of("selectInputs","reviewInputs","confirmInputs","inspectInputs","queryInputs","cancelInputs").contains(command))throw new SecurityException("没有这项原群输入动作");if(inputSnapshot!=null&&inputSnapshot.optBoolean("registered")&&java.util.Set.of("selectInputs","reviewInputs","confirmInputs").contains(command))throw new SecurityException("原输入已登记，只核对/停止；不重体、不重签旧job");JSONObject payload=new JSONObject(input.optJSONObject("payload")==null?"{}":input.getJSONObject("payload").toString()).put("windowId",inputWindow).put("taskId",taskId);inputSnapshot=owner.handle(nativeActivity,command,payload).getJSONObject("snapshot");check();return snapshot();}
            case "query":{query(input.getString("taskId"));return snapshot();}
            case "cancel":{
                String selected=input.getString("taskId");exactTask(selected);JSONObject scope=tasks.originalRemoteInputScope(selected),task=tasks.get(selected,false);tasks.requestCancel(selected,scope.getString("jobOperationId"));String job=task.optString("remoteInputJobId");if(job.isEmpty())tasks.cancelRemoteInputBeforeJob(selected);else{remote.requireProfileBinding(scope.getString("profileId"),scope.getString("profileGeneration"));JSONObject actual=remote.handle("cancelJob",new JSONObject().put("profileId",scope.getString("profileId")).put("serviceBase",scope.getString("serviceBase")).put("_profileBinding",scope.getString("profileGeneration")).put("jobId",job).put("jobOperationId",scope.getString("jobOperationId")));tasks.updateExternal(selected,actual);}check();return snapshot();}
            case "reviewResult":return reviewResult(input.getString("taskId"),input.getString("replyEventId"));
            case "inspectDelivery":{String selected=input.getString("taskId");exactTask(selected);JSONObject row=tasks.originalGroupRemoteReturn(selected,input.getString("operationId"));if(!row.getString("state").equals("receipt"))throw new SecurityException("原群成果冻结尚未确认，不能猜投递目标");JSONObject saved=row.getJSONObject("receipt").getJSONObject("artifact"),scope=row.getJSONObject("arguments").getJSONObject("scope");String delivery=UUID.nameUUIDFromBytes(("group-delivery:"+requestId+":"+saved.getString("artifactId")+":"+scope.getJSONObject("groupInputSource").getString("audience")).getBytes(StandardCharsets.UTF_8)).toString();lastDelivery=groups.ownerCommand("delivery.inspect",new JSONObject().put("deliveryId",delivery));return snapshot();}
            case "queryReturn":{String selected=input.getString("taskId");exactTask(selected);resultOperation=tasks.originalGroupRemoteReturn(selected,input.getString("operationId"));if(resultOperation.getString("state").equals("unknown")){source=groups.remoteInputSourceForOwner(requestId);RunControl read=new RunControl();read.retainAuthorityCheck(this::check);var actual=artifacts.findRemoteResult(resultOperation.getJSONObject("arguments").getJSONObject("scope"),source,read);if(actual!=null){tasks.reconcileGroupRemoteReturn(selected,input.getString("operationId"),actual);resultOperation=tasks.originalGroupRemoteReturn(selected,input.getString("operationId"));}}check();return snapshot();}
            default:return confirmResult(input);
        }
    }
    private JSONObject query(String selected)throws Exception{
        exactTask(selected);JSONObject scope=tasks.originalRemoteInputScope(selected);remote.requireProfileBinding(scope.getString("profileId"),scope.getString("profileGeneration"));JSONObject actual=remote.queryInputJob(scope,tasks.get(selected,false).optString("remoteInputJobId"));check();if(actual.has("inputState"))tasks.reconcileRemoteInputs(selected,actual);lastJob=actual;taskId=selected;return actual;
    }
    private JSONObject reviewResult(String selected,String replyEvent)throws Exception{
        JSONObject actual=query(selected),scope=tasks.originalRemoteInputScope(selected);source=groups.remoteInputSourceForOwner(requestId);source.checkCurrent();JSONObject api=actual.optJSONObject("externalGroupApiRead");
        if(!actual.optString("status").equals("completed")||!actual.optBoolean("protocolVerified")||!actual.optBoolean("readOnlyConfirmed")||!actual.optBoolean("externalToolsDisabled")||actual.optBoolean("outputTruncated")||api==null||!"apiKey".equals(api.optString("authMode"))||!api.optBoolean("accountReadVerified")||!api.optBoolean("postTurnAccountReadVerified")||!api.optBoolean("generationCheckedAfterTurn")||!api.optBoolean("configuredCredentialSourceVerified")||api.opt("billingBackendVerified")!=Boolean.FALSE||!scope.getJSONObject("externalGroupApiMode").getString("credentialGeneration").equals(api.optString("credentialGeneration")))throw new SecurityException("原API-mode只读job尚无完整终态输出；不以配置、未知或部分文字冒成功成果");
        Object raw=actual.opt("output");if(!(raw instanceof String))throw new SecurityException("原worker没有可冻结的实际文字输出");byte[] bytes=((String)raw).getBytes(StandardCharsets.UTF_8);if(bytes.length<1||bytes.length>196608||bytes.length>source.originalRequest().maxMediaBytes)throw new SecurityException("原文字结果超过有界群成果范围，未截断冒完整");
        JSONObject target=groups.remoteReplyContextForOwner(source,replyEvent);JSONObject facts=new JSONObject().put("taskId",selected).put("runId",scope.getString("jobOperationId")).put("jobId",actual.getString("id")).put("jobOperationId",actual.getString("operationId")).put("threadId",actual.getString("threadId")).put("turnId",actual.getString("turnId")).put("inputScopeHash",TaskStore.capabilityFingerprint(scope)).put("groupInputSource",scope.getJSONObject("groupInputSource")).put("replyContext",target).put("mimeType","application/octet-stream").put("bytes",bytes.length).put("sha256",dev.pocketengine.features.local.project.ProjectSources.sha256(bytes)).put("inferenceAudience","EXTERNAL_GROUP").put("privateBookImported",false).put("workerApiRead",api).put("businessSuccessVerified",false).put("expiresAt",System.currentTimeMillis()+120000);
        facts.put("operationId",UUID.nameUUIDFromBytes(("pocketworld/group-remote-result/v1/"+scope.getString("jobOperationId")+"/"+facts.getString("sha256")).getBytes(StandardCharsets.UTF_8)).toString());try{JSONObject retained=tasks.originalGroupRemoteReturn(selected,facts.getString("operationId")).getJSONObject("arguments").getJSONObject("scope");if(!retained.getString("sha256").equals(facts.getString("sha256"))||!retained.getString("inputScopeHash").equals(facts.getString("inputScopeHash")))throw new SecurityException("原冻结记录来源变化");facts=retained;}catch(IllegalArgumentException notRegistered){}check();review=new ReturnApproval(this,source,facts,(String)raw,target);java.util.Arrays.fill(bytes,(byte)0);return snapshot();
    }
    private JSONObject confirmResult(JSONObject input)throws Exception{
        ReturnApproval approved=review;if(approved==null||input.opt("contentAndAudienceAcknowledged")!=Boolean.TRUE||!approved.digest.equals(input.optString("digest")))throw new SecurityException("请在当前原生页核对这份实际内容与确切原群受众");approved.checkCurrent();approved.originalSource().checkCurrent();JSONObject actual=query(approved.scope().getString("taskId"));if(!approved.scope().getString("sha256").equals(dev.pocketengine.features.local.project.ProjectSources.sha256(actual.getString("output").getBytes(StandardCharsets.UTF_8)))||!approved.scope().getString("turnId").equals(actual.optString("turnId")))throw new SecurityException("所阅原成果发生变化，未冻结/发送");
        resultOperation=tasks.prepareGroupRemoteReturn(approved);String state=resultOperation.getString("state");
        if(state.equals("prepared")){var freeze=tasks.beforeGroupRemoteReturn(approved);try{var saved=artifacts.retainRemoteResult(freeze);tasks.recordGroupRemoteReturn(approved,saved);resultOperation=tasks.originalGroupRemoteReturn(approved.scope().getString("taskId"),approved.scope().getString("operationId"));}catch(Exception unknown){review=null;throw new IllegalStateException("原群成果冻结回执未确认，只核对原编号；不重写原件或自动发送",unknown);}}
        if(!resultOperation.getString("state").equals("receipt")){review=null;throw new IllegalStateException("原成果冻结效果未知，只查询；未另建产物/发送");}
        approved.frozen=resultOperation.getJSONObject("receipt").getJSONObject("artifact").toString();approved.checkOriginalReceipt();lastDelivery=groups.sendRemoteResult(approved);review=null;check();return snapshot();
    }
    public JSONObject snapshot()throws Exception{
        check();JSONObject value=new JSONObject().put("pageId",pageId).put("requestId",requestId).put("sourceTaskId",parentTask).put("remoteProfiles",remote.snapshot().getJSONArray("profiles")).put("jobs",tasks.groupRemoteInputTasksForOwner(requestId,parentTask)).put("scope","authenticated_group_to_reviewed_api_mode_read_only_analysis").put("privateBookImported",false);
        if(source!=null){value.put("groupSource",source.view());try{value.put("replyContexts",channels.originalGroupRemoteReplyContexts(groups,source));}catch(Exception unavailable){value.put("replyContexts",new JSONArray()).put("replyContextUnavailable",true);}}
        if(inputSnapshot!=null)value.put("input",new JSONObject(inputSnapshot.toString()));if(review!=null)value.put("returnReview",review.metadata());if(lastJob!=null){JSONObject job=new JSONObject(lastJob.toString());job.remove("output");value.put("originalJob",job);}if(resultOperation!=null)value.put("returnOperation",resultOperation);if(lastDelivery!=null)value.put("delivery",lastDelivery);check();return value;
    }
    public static final class ReturnApproval {
        private final RemoteGroupInputs page;private final GroupsModule.RemoteInputSource source;private final String facts,text,digest,deliveryContext;private final long reviewExpiresAt=System.currentTimeMillis()+120000;private volatile String frozen;
        private ReturnApproval(RemoteGroupInputs page,GroupsModule.RemoteInputSource source,JSONObject facts,String text,JSONObject target)throws Exception{this.page=page;this.source=source;this.facts=facts.toString();this.text=text;deliveryContext=target.toString();digest=TaskStore.capabilityFingerprint(new JSONObject().put("originalFreezeScopeHash",TaskStore.capabilityFingerprint(facts)).put("replyContext",target).put("reviewExpiresAt",reviewExpiresAt));}
        public JSONObject scope()throws Exception{return new JSONObject(facts);}
        public JSONObject deliveryContext()throws Exception{return new JSONObject(deliveryContext);}
        public JSONObject metadata()throws Exception{return new JSONObject().put("scope",scope().put("replyContext",deliveryContext())).put("originalFreezeScopeHash",TaskStore.capabilityFingerprint(scope())).put("digest",digest).put("reviewExpiresAt",reviewExpiresAt).put("originalScopeExpiresAt",scope().getLong("expiresAt")).put("text",text).put("actualUtf8Bytes",text.getBytes(StandardCharsets.UTF_8).length);}
        /** Pure lifecycle/expiry only; original SQL may invoke this without entering Core/registry. */
        public void checkCurrent()throws Exception{page.check();if(page.review!=this||System.currentTimeMillis()>reviewExpiresAt)throw new SecurityException("原群成果内容/目标审阅已失效");}
        public boolean issuedBy(TaskStore tasks){return page.tasks==tasks;}
        public GroupsModule.RemoteInputSource originalSource(){return source;}
        public byte[] exactBytes()throws Exception{checkCurrent();source.checkCurrent();return text.getBytes(StandardCharsets.UTF_8);}
        public JSONObject saved()throws Exception{if(frozen==null)throw new SecurityException("没有原群不可变产物回执");return new JSONObject(frozen);}
        public void checkOriginalReceipt()throws Exception{checkCurrent();JSONObject row=page.tasks.originalGroupRemoteReturn(scope().getString("taskId"),scope().getString("operationId"));if(!row.optString("state").equals("receipt")||!TaskStore.capabilityFingerprint(saved()).equals(TaskStore.capabilityFingerprint(row.getJSONObject("receipt").getJSONObject("artifact"))))throw new SecurityException("原群冻结产物未登记到此原操作");}
        public RunControl readControl(){RunControl value=new RunControl();value.retainAuthorityCheck(()->{checkCurrent();source.checkCurrent();});return value;}
    }
    @Override public void close(){closed=true;review=null;if(inputWindow!=null)owner.close(inputWindow);}
}
